<script setup lang="ts">
type Keluarga = { idKeluarga: number; namaKeluarga: string }
type Jemaat = { idJemaat: number; idKeluarga: number; namaKeluarga: string; namaLengkap: string; jenisKelamin: 'LAKI_LAKI' | 'PEREMPUAN'; tanggalLahir: string; alamat: string; telepon: string | null; statusJemaat: string }
type FormJemaat = { idKeluarga: number | null; namaLengkap: string; jenisKelamin: 'LAKI_LAKI' | 'PEREMPUAN'; tanggalLahir: string; alamat: string; telepon: string; statusJemaat: string }
type NamaField = keyof FormJemaat
const { apiFetch } = useApi()
const tokenAdmin = useCookie<string | null>('gkii_admin_token')
const authorization = computed(() => ({ Authorization: `Bearer ${tokenAdmin.value}` }))
const formAwal = (): FormJemaat => ({ idKeluarga: null, namaLengkap: '', jenisKelamin: 'LAKI_LAKI', tanggalLahir: '', alamat: '', telepon: '', statusJemaat: 'AKTIF' })
const form = reactive<FormJemaat>(formAwal())
const kesalahanForm = reactive<Record<NamaField, string>>({ idKeluarga: '', namaLengkap: '', jenisKelamin: '', tanggalLahir: '', alamat: '', telepon: '', statusJemaat: '' })
const formTerbuka = ref(false); const idJemaatDiedit = ref<number | null>(null); const sedangMenyimpan = ref(false); const sedangMenghapus = ref<number | null>(null); const pesanError = ref(''); const pesanSukses = ref(''); const ringkasanError = ref<HTMLElement | null>(null)
const { data: dataAwal, pending, error, refresh } = await useAsyncData('admin-jemaat', async () => { const [jemaatResponse, keluargaResponse] = await Promise.all([apiFetch<Jemaat[]>('/jemaat', { headers: authorization.value }), apiFetch<Keluarga[]>('/keluarga', { headers: authorization.value })]); return { daftarJemaat: jemaatResponse.data, daftarKeluarga: keluargaResponse.data } })
const daftarJemaat = computed(() => dataAwal.value?.daftarJemaat ?? []); const daftarKeluarga = computed(() => dataAwal.value?.daftarKeluarga ?? []); const keluargaTersedia = computed(() => daftarKeluarga.value.length > 0); const modeEdit = computed(() => idJemaatDiedit.value !== null)
function formatTanggal(tanggal: string) { return new Intl.DateTimeFormat('id-ID', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(tanggal)) }
function bersihkanKesalahan() { for (const field of Object.keys(kesalahanForm) as NamaField[]) kesalahanForm[field] = '' }
function validasiField(field: NamaField) { if (field === 'idKeluarga') { kesalahanForm.idKeluarga = form.idKeluarga ? '' : 'Pilih keluarga.'; return !kesalahanForm.idKeluarga }; const nilai = typeof form[field] === 'string' ? form[field].trim() : ''; if (['namaLengkap', 'tanggalLahir', 'alamat', 'statusJemaat'].includes(field) && !nilai) { kesalahanForm[field] = 'Field ini wajib diisi.'; return false }; kesalahanForm[field] = ''; return true }
function validasiForm() { return (['idKeluarga', 'namaLengkap', 'tanggalLahir', 'alamat', 'statusJemaat'] as NamaField[]).every(validasiField) }
function bukaFormTambah() { Object.assign(form, formAwal()); bersihkanKesalahan(); idJemaatDiedit.value = null; pesanError.value = ''; formTerbuka.value = true }
function bukaFormEdit(jemaat: Jemaat) { Object.assign(form, { idKeluarga: jemaat.idKeluarga, namaLengkap: jemaat.namaLengkap, jenisKelamin: jemaat.jenisKelamin, tanggalLahir: jemaat.tanggalLahir, alamat: jemaat.alamat, telepon: jemaat.telepon ?? '', statusJemaat: jemaat.statusJemaat }); bersihkanKesalahan(); idJemaatDiedit.value = jemaat.idJemaat; pesanError.value = ''; formTerbuka.value = true }
function tutupForm() { if (!sedangMenyimpan.value) { formTerbuka.value = false; pesanError.value = ''; bersihkanKesalahan() } }
async function simpanJemaat() { pesanError.value = ''; pesanSukses.value = ''; if (!validasiForm() || !form.idKeluarga) { pesanError.value = 'Periksa kembali data jemaat yang wajib diisi.'; await nextTick(); ringkasanError.value?.focus(); return }; sedangMenyimpan.value = true; const body = { ...form, idKeluarga: form.idKeluarga, namaLengkap: form.namaLengkap.trim(), alamat: form.alamat.trim(), telepon: form.telepon.trim() || null, statusJemaat: form.statusJemaat.trim() }; try { if (modeEdit.value && idJemaatDiedit.value) { await apiFetch<Jemaat>(`/jemaat/${idJemaatDiedit.value}`, { method: 'PUT', headers: authorization.value, body }); pesanSukses.value = 'Data jemaat berhasil diperbarui.' } else { await apiFetch<Jemaat>('/jemaat', { method: 'POST', headers: authorization.value, body }); pesanSukses.value = 'Data jemaat berhasil ditambahkan.' }; formTerbuka.value = false; await refresh() } catch (error: unknown) { const fetchError = error as { data?: { message?: string } }; pesanError.value = fetchError.data?.message ?? 'Data jemaat belum dapat disimpan. Silakan coba kembali.' } finally { sedangMenyimpan.value = false } }
async function hapusJemaat(jemaat: Jemaat) { if (!window.confirm(`Hapus jemaat "${jemaat.namaLengkap}"? Tindakan ini tidak dapat dibatalkan.`)) return; pesanError.value = ''; pesanSukses.value = ''; sedangMenghapus.value = jemaat.idJemaat; try { await apiFetch<null>(`/jemaat/${jemaat.idJemaat}`, { method: 'DELETE', headers: authorization.value }); pesanSukses.value = 'Data jemaat berhasil dihapus.'; await refresh() } catch (error: unknown) { const fetchError = error as { data?: { message?: string } }; pesanError.value = fetchError.data?.message ?? 'Data jemaat belum dapat dihapus. Silakan coba kembali.' } finally { sedangMenghapus.value = null } }
useHead({ title: 'Jemaat | Admin GKII Jajar Solo' }); definePageMeta({ layout: 'admin', middleware: ['admin'] })
</script>

<template><div><div class="page-heading"><div><p class="page-label mb-2">MANAJEMEN JEMAAT</p><h1 class="h2 mb-2">Jemaat</h1><p class="text-secondary mb-0">Kelola data anggota jemaat dan hubungkan ke data keluarganya.</p></div><button type="button" class="btn btn-gkii-primary" :disabled="!keluargaTersedia" @click="bukaFormTambah">Tambah Jemaat</button></div><div v-if="!pending && !keluargaTersedia" class="alert alert-warning" role="alert">Buat minimal satu keluarga sebelum menambahkan jemaat.</div><div v-if="pesanSukses" class="alert alert-success" role="status">{{ pesanSukses }}</div><div v-if="pesanError && !formTerbuka" class="alert alert-danger" role="alert">{{ pesanError }}</div>
<section class="data-panel"><div class="data-panel-header"><div><h2 class="h5 mb-1">Daftar Jemaat</h2><p class="text-secondary small mb-0">{{ daftarJemaat.length }} jemaat tercatat</p></div><button type="button" class="btn btn-outline-gkii" :disabled="pending" @click="refresh()">Muat Ulang</button></div><div v-if="pending" class="p-4" aria-live="polite" aria-busy="true"><div class="placeholder-glow"><span class="placeholder col-12 mb-3"></span><span class="placeholder col-10 mb-3"></span></div></div><div v-else-if="daftarJemaat.length" class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Nama</th><th>Keluarga</th><th>Jenis Kelamin</th><th>Status</th><th>Kontak</th><th class="text-end">Aksi</th></tr></thead><tbody><tr v-for="jemaat in daftarJemaat" :key="jemaat.idJemaat"><td><p class="mb-1 fw-semibold">{{ jemaat.namaLengkap }}</p><small class="text-secondary">{{ formatTanggal(jemaat.tanggalLahir) }}</small></td><td>{{ jemaat.namaKeluarga }}</td><td>{{ jemaat.jenisKelamin === 'LAKI_LAKI' ? 'Laki-laki' : 'Perempuan' }}</td><td><span class="status-badge">{{ jemaat.statusJemaat }}</span></td><td>{{ jemaat.telepon || '—' }}</td><td class="text-end"><div class="d-inline-flex gap-2"><button type="button" class="btn btn-sm btn-outline-gkii" @click="bukaFormEdit(jemaat)">Edit</button><button type="button" class="btn btn-sm btn-outline-danger" :disabled="sedangMenghapus === jemaat.idJemaat" @click="hapusJemaat(jemaat)">{{ sedangMenghapus === jemaat.idJemaat ? 'Menghapus...' : 'Hapus' }}</button></div></td></tr></tbody></table></div><div v-else class="empty-state p-5 text-center"><h2 class="h5 mb-2">{{ error ? 'Data belum dapat dimuat' : 'Belum ada jemaat' }}</h2><p class="text-secondary mb-3">{{ error ? 'Periksa koneksi backend atau token login, lalu coba muat ulang.' : 'Tambahkan data jemaat setelah keluarga tersedia.' }}</p><button v-if="!error && keluargaTersedia" type="button" class="btn btn-gkii-primary" @click="bukaFormTambah">Tambah Jemaat</button></div></section>
<div v-if="formTerbuka" class="modal-backdrop" @click.self="tutupForm" @keydown.esc="tutupForm"><section class="form-modal" role="dialog" aria-modal="true" aria-labelledby="judulFormJemaat"><div class="form-modal-header"><div><p class="page-label mb-2">{{ modeEdit ? 'UBAH JEMAAT' : 'TAMBAH JEMAAT' }}</p><h2 id="judulFormJemaat" class="h4 mb-0">{{ modeEdit ? 'Perbarui data jemaat' : 'Catat jemaat baru' }}</h2></div><button type="button" class="close-button" aria-label="Tutup formulir jemaat" :disabled="sedangMenyimpan" @click="tutupForm">Tutup</button></div><form @submit.prevent="simpanJemaat"><div v-if="pesanError" ref="ringkasanError" class="alert alert-danger" role="alert" tabindex="-1">{{ pesanError }}</div><div class="row g-3"><div class="col-12"><label for="idKeluarga" class="form-label">Keluarga</label><select id="idKeluarga" v-model.number="form.idKeluarga" class="form-select" :class="{ 'is-invalid': kesalahanForm.idKeluarga }" @blur="validasiField('idKeluarga')"><option :value="null" disabled>Pilih keluarga</option><option v-for="keluarga in daftarKeluarga" :key="keluarga.idKeluarga" :value="keluarga.idKeluarga">{{ keluarga.namaKeluarga }}</option></select><div class="invalid-feedback">{{ kesalahanForm.idKeluarga }}</div></div><div class="col-12"><label for="namaLengkap" class="form-label">Nama lengkap</label><input id="namaLengkap" v-model="form.namaLengkap" class="form-control" :class="{ 'is-invalid': kesalahanForm.namaLengkap }" @blur="validasiField('namaLengkap')"><div class="invalid-feedback">{{ kesalahanForm.namaLengkap }}</div></div><div class="col-md-6"><label for="jenisKelamin" class="form-label">Jenis kelamin</label><select id="jenisKelamin" v-model="form.jenisKelamin" class="form-select"><option value="LAKI_LAKI">Laki-laki</option><option value="PEREMPUAN">Perempuan</option></select></div><div class="col-md-6"><label for="tanggalLahir" class="form-label">Tanggal lahir</label><input id="tanggalLahir" v-model="form.tanggalLahir" type="date" class="form-control" :class="{ 'is-invalid': kesalahanForm.tanggalLahir }" @blur="validasiField('tanggalLahir')"><div class="invalid-feedback">{{ kesalahanForm.tanggalLahir }}</div></div><div class="col-12"><label for="alamat" class="form-label">Alamat</label><textarea id="alamat" v-model="form.alamat" rows="3" class="form-control" :class="{ 'is-invalid': kesalahanForm.alamat }" @blur="validasiField('alamat')"></textarea><div class="invalid-feedback">{{ kesalahanForm.alamat }}</div></div><div class="col-md-6"><label for="telepon" class="form-label">Telepon <span class="text-secondary">(opsional)</span></label><input id="telepon" v-model="form.telepon" type="tel" class="form-control"></div><div class="col-md-6"><label for="statusJemaat" class="form-label">Status jemaat</label><input id="statusJemaat" v-model="form.statusJemaat" class="form-control" placeholder="Contoh: AKTIF" :class="{ 'is-invalid': kesalahanForm.statusJemaat }" @blur="validasiField('statusJemaat')"><div class="invalid-feedback">{{ kesalahanForm.statusJemaat }}</div></div></div><div class="d-flex justify-content-end gap-2 mt-4"><button type="button" class="btn btn-outline-gkii" :disabled="sedangMenyimpan" @click="tutupForm">Batal</button><button type="submit" class="btn btn-gkii-primary" :disabled="sedangMenyimpan">{{ sedangMenyimpan ? 'Menyimpan...' : modeEdit ? 'Simpan Perubahan' : 'Simpan Jemaat' }}</button></div></form></section></div>
</div></template>
<style scoped>
.page-heading,.data-panel-header,.form-modal-header{align-items:flex-start;display:flex;gap:1rem;justify-content:space-between}.page-heading{margin-bottom:1.5rem}.page-label{color:var(--gkii-gold-500);font-size:.72rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase}.data-panel{background:var(--gkii-surface);border:1px solid var(--gkii-border);box-shadow:0 .5rem 1.5rem rgb(18 63 50 / 6%)}.data-panel-header{border-bottom:1px solid var(--gkii-border);padding:1.25rem 1.5rem}th{background:var(--gkii-cream);color:var(--gkii-green-900);font-size:.75rem;letter-spacing:.08em;text-transform:uppercase}.status-badge{background:var(--gkii-green-100);border-radius:999px;color:var(--gkii-green-900);font-size:.75rem;font-weight:700;padding:.35rem .65rem}.empty-state{background:var(--gkii-surface)}.placeholder{background-color:var(--gkii-green-100)}.modal-backdrop{align-items:center;background:rgb(0 0 0 / 55%);display:flex;inset:0;justify-content:center;padding:1rem;position:fixed;z-index:1100}.form-modal{background:var(--gkii-surface);box-shadow:0 1.5rem 4rem rgb(0 0 0 / 28%);max-height:calc(100vh - 2rem);overflow-y:auto;padding:1.5rem;width:min(100%,44rem)}.form-modal-header{border-bottom:1px solid var(--gkii-border);margin-bottom:1.5rem;padding-bottom:1rem}.form-control,.form-select{min-height:44px}textarea.form-control{min-height:auto}.close-button{background:transparent;border:1px solid var(--gkii-border);color:var(--gkii-green-900);min-height:44px;padding:0 .9rem}.close-button:hover{background:var(--gkii-cream)}.btn:focus-visible,.close-button:focus-visible,.form-control:focus-visible,.form-select:focus-visible{outline:3px solid var(--gkii-gold-500);outline-offset:2px}@media(max-width:575.98px){.page-heading,.data-panel-header,.form-modal-header{align-items:stretch;flex-direction:column}.form-modal{padding:1.25rem}}
</style>
